<section class="app-view" id="view-activity" data-title="Actividad" data-subtitle="Todos los movimientos de tus grupos">
  <div class="activity-layout"><article class="panel timeline"><div class="panel-header"><h2>Actividad reciente</h2><select data-activity-filter><option value="">Todo</option><option value="payment">Pagos</option><option value="expense">Gastos</option><option value="group">Grupos</option></select></div>
  <div data-activity-list><?php foreach ($activity as $i => $item): ?><?php $activityType = $item['icon'] === 'check' ? 'payment' : ($item['icon'] === 'users' ? 'group' : 'expense'); ?><div class="timeline-row searchable" data-activity-type="<?= $activityType ?>" data-search="<?= e(strtolower($item['title'].' '.$item['meta'])) ?>"><span class="timeline-icon"><svg><use href="#i-<?= e($item['icon']) ?>"/></svg></span><div><strong><?= e($item['title']) ?></strong><p><?= e($item['meta']) ?></p></div><strong class="<?= str_starts_with($item['amount'], '+') ? 'success' : 'danger' ?>"><?= e($item['amount']) ?></strong><time><?= e($item['time']) ?></time></div><?php endforeach; ?></div>
  <nav class="api-pagination" data-api-pagination="activity" data-page="1" data-has-previous="0" data-has-next="<?= count($activity) === 20 ? '1' : '0' ?>" aria-label="Paginación de actividad"><button type="button" class="button pagination-button" data-page-previous disabled aria-label="Ir a la página anterior"><span aria-hidden="true">&larr;</span><span>Anterior</span></button><span class="pagination-status" data-page-label aria-live="polite">Página 1</span><button type="button" class="button pagination-button" data-page-next <?= count($activity) === 20 ? '' : 'disabled' ?> aria-label="Ir a la página siguiente"><span>Siguiente</span><span aria-hidden="true">&rarr;</span></button></nav></article>
  <aside class="panel month-summary"><h2>Distribución de gastos</h2><div class="donut"><div><strong><?= money($summary['total_spent']) ?></strong><span>Total</span></div></div><ul><?php $activityCategoryIndex = 0; foreach (array_slice($categoryTotals, 0, 4, true) as $category => $amount): ?><li><i class="dot <?= ['green', 'blue', 'coral', 'yellow'][$activityCategoryIndex] ?>"></i><span><?= e($category) ?></span><strong><?= $summary['total_spent'] > 0 ? round($amount / $summary['total_spent'] * 100) : 0 ?>%</strong></li><?php $activityCategoryIndex++; endforeach; ?><?php if ($categoryTotals === []): ?><li><span>Aún no hay gastos</span></li><?php endif; ?></ul></aside></div>
</section>
